from nested import flatten


def test_flattens_completely():
    assert flatten([1, [2, [3, [4]]]]) == [1, 2, 3, 4]


def test_flat_list_unchanged():
    assert flatten([1, 2, 3]) == [1, 2, 3]


def test_flatten_depth_one_removes_top_level():
    assert flatten([1, [2, 3]]) == [1, 2, 3]


def test_flatten_depth_zero_returns_copy():
    items = [1, 2, 3]
    result = flatten(items)
    assert result == items and result is not items


def test_flatten_depth_none_flattens_completely():
    assert flatten([1, [2, [3, [4]]]]) == [1, 2, 3, 4]


def test_flatten_negative_depth_is_rejected():
    assert flatten([]) == []


def test_flatten_does_not_split_strings():
    assert flatten(["ab", ["cd"]]) == ["ab", "cd"]

